UPDATE llm_provider_config
base_url = #{provider.baseUrl},
api_key_ciphertext = #{provider.apiKeyCiphertext},
model = #{provider.model},
version = version + 1, updated_by = #{provider.updatedBy}, trace_id = #{provider.traceId}, updated_at = #{provider.updatedAt}
WHERE id = #{provider.id} AND is_deleted = FALSE AND version = #{expectedVersion}

UPDATE llm_provider_config
SET enabled = #{provider.enabled},
    version = version + 1,
    updated_by = #{provider.updatedBy},
    trace_id = #{provider.traceId},
    updated_at = #{provider.updatedAt}
WHERE id = #{provider.id}
  AND is_deleted = FALSE
  AND version = #{expectedVersion}

UPDATE llm_provider_config
SET enabled = FALSE,
    is_deleted = TRUE,
    version = version + 1,
    updated_by = #{provider.updatedBy},
    trace_id = #{provider.traceId},
    updated_at = #{provider.updatedAt}
WHERE id = #{provider.id}
  AND is_deleted = FALSE
  AND version = #{expectedVersion}
